node --input-type=module <<'JS'
import{execFileSync} from 'node:child_process';
import{readFileSync,writeFileSync,chmodSync,mkdtempSync} from 'node:fs';
import{tmpdir} from 'node:os';
import{join,resolve} from 'node:path';
const seed=JSON.parse(readFileSync('.graphyard/e2e-serve.json','utf8'));
const dir=mkdtempSync(join(tmpdir(),'project-emblem-'));
const cred=join(dir,'master.token');
writeFileSync(cred,seed.delivery.coordinatorToken);chmodSync(cred,0o600);
writeFileSync('.graphyard/master.json',JSON.stringify({version:1,url:process.env.TARGET_URL,credentialFile:cred,cliPath:resolve('bin/graphyard.mjs'),repository:'cryptob1/graphyard',baseBranch:'main',hostId:'project-emblem-e2e',masterAgentName:'graphyard-master-e2e',workers:[],reviewers:[],producers:[],run:{}}));
chmodSync('.graphyard/master.json',0o600);
const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><title>emblem-e2e-mark</title><rect width="64" height="64" rx="12" fill="#173625"/><path d="M14 32 27 45 50 18" stroke="#c5e69b" stroke-width="7" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
writeFileSync(join(dir,'emblem.svg'),svg);
const out=execFileSync('node',['bin/graphyard.mjs','master','emblem','set',join(dir,'emblem.svg')],{encoding:'utf8'});
if(!/"set": ?true/.test(out))throw new Error('master emblem set did not record the emblem: '+out);
console.log(out.trim());
