node --input-type=module <<'JS'
import{chromium,expect} from '@playwright/test';
const b=await chromium.launch();
try{
const p=await b.newPage({viewport:{width:1280,height:900}});
await p.goto(process.env.TARGET_URL+'?sign-in');
await p.getByLabel('Access token').fill('{{token}}');
await p.getByRole('button',{name:'Open control plane'}).click();
const status=await (await p.request.get(new URL('/api/status',process.env.TARGET_URL).href,{headers:{Authorization:'Bearer {{token}}'}})).json();
const bar=p.locator('.top-bar');
await expect(bar.locator('.project-name')).toHaveText(status.repository);
const img=bar.locator('.project-emblem');
await expect(img).toHaveAttribute('src',/\/favicon\.svg$/);
await expect(img).toBeVisible();
expect(await img.evaluate(e=>e.naturalWidth)).toBeGreaterThan(0);
const r=await p.request.get(new URL('/favicon.svg',process.env.TARGET_URL).href);
expect(r.headers()['content-type']).toContain('image/svg+xml');
const text=await r.text();
expect(text.includes('emblem-e2e-mark')).toBe(true);
expect(text.includes('<script')).toBe(false);
await expect(p.locator('link[rel="icon"]')).toHaveAttribute('href','/favicon.svg');
}finally{await b.close()}
