node --input-type=module <<'JS'
import{execFileSync} from 'node:child_process';
import{writeFileSync,mkdtempSync} from 'node:fs';
import{tmpdir} from 'node:os';
import{join} from 'node:path';
const dir=mkdtempSync(join(tmpdir(),'project-emblem-refused-'));
const file=join(dir,'emblem.svg');
const head='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">';
const cases=[
[head+'<script>alert(1)</script><rect width="64" height="64"/></svg>','script element'],
[head.replace('<svg ','<svg onload="alert(1)" ')+'<rect width="64" height="64"/></svg>','onload'],
[head+'<image href="https://example.invalid/mark.png"/></svg>','outside itself'],
[head+'<rect width="64" height="64"/>'+'<circle cx="6" cy="6" r="3" fill="#c5e69b"/>'.repeat(220)+'</svg>','8 KB'],
];
for(const[svg,needle]of cases){
writeFileSync(file,svg);
let refused=false,reason='';
try{execFileSync('node',['bin/graphyard.mjs','master','emblem','set',file],{encoding:'utf8'});}
catch(error){refused=true;reason=String(error.stderr);}
if(!refused)throw new Error('accepted an emblem it should refuse ('+needle+')');
if(!reason.includes(needle))throw new Error('refused without naming '+needle+': '+reason);
console.log(needle+' refused');
}
